select * from jsonb_populate_recordset(null::public.announcements, $iejson$[{"id": "6b6d4bfc-414b-43f3-8ca9-2c1e7bbd90b6", "type": "general", "title": "Reuniones con representantes de familia", "active": true, "end_date": "2027-02-01", "priority": "baja", "created_at": "2026-10-04T17:42:22.380299+00:00", "start_date": "2026-10-04", "description": "Las reuniones con las familias se convocan de forma periódica por grado. Las citaciones se envían con antelación y también se hacen públicas por los canales oficiales del colegio."}, {"id": "8c5fc885-0f5c-41ce-96d8-b794db6305cd", "type": "importante", "title": "Cierre administrativo del segundo semestre", "active": true, "end_date": "2026-12-03", "priority": "alta", "created_at": "2026-10-04T17:42:22.380299+00:00", "start_date": "2026-10-04", "description": "Durante el periodo de cierre administrativo los trámites quedan suspendidos. Los estudiantes que necesiten diplomas, certificados o constancias deben solicitarlos con anticipación."}, {"id": "8f827efe-710a-491e-8cae-15adfcc031c8", "type": "matricula", "title": "Proceso de admisión 2028", "active": true, "end_date": "2027-02-01", "priority": "alta", "created_at": "2026-10-04T17:42:22.380299+00:00", "start_date": "2026-10-04", "description": "Las inscripciones para el año lectivo 2027 abren en fechas que confirmaremos oportunamente a través de este portal. Las familias interesadas pueden solicitar información en la secretaría del colegio dentro del horario de atención."}, {"id": "1ad802e0-032a-40da-9c72-7cdf967e7844", "type": "general", "title": "Calendario académico 2027", "active": true, "end_date": "2027-03-03", "priority": "media", "created_at": "2026-10-04T17:42:22.380299+00:00", "start_date": "2026-10-04", "description": "El calendario académico del año en curso define los periodos de evaluación, las semanas de receso y las fechas de entrega de boletines. La versión completa se publica en la sección de documentos de este portal."}, {"id": "c556426d-7ceb-4587-a27f-7a420cf4b60c", "type": "general", "title": "Uniformes y presentación personal", "active": true, "end_date": "2027-01-02", "priority": "media", "created_at": "2026-10-04T17:42:22.380299+00:00", "start_date": "2026-10-04", "description": "Recordamos los parámetros de presentación personal y de uniforme establecidos por el manual de convivencia. El uso correcto del uniforme es un requisito para la asistencia a clases y a las actividades de la jornada escolar."}]$iejson$::jsonb);

