select * from jsonb_populate_recordset(null::public.events, $iejson$[{"id": "3f567aad-e230-428e-b98f-66674fa82f7b", "date": "2026-10-20", "time": "07:00", "image": null, "title": "Inicio del segundo semestre 2026", "active": true, "endTime": "12:00", "category": "academic", "location": "Patio principal", "created_at": "2026-10-04T17:45:27.477283+00:00", "description": "Arranque del segundo semestre del ano escolar 2026 con la presentacion del equipo docente y la programacion de actividades del periodo.", "fullDescription": "Arranque del segundo semestre del ano escolar 2026. La jornada inicia con la programacion de actividades, la presentacion del equipo docente y la entrega de los calendarios de evaluacion por grado. Se recomienda la asistencia de los estudiantes y sus familias."}, {"id": "24268363-d76a-44f1-8bd7-f6f79baae576", "date": "2026-11-14", "time": "08:00", "image": null, "title": "Festival de la cultura colombiana", "active": true, "endTime": "13:00", "category": "cultural", "location": "Auditorio y patio principal", "created_at": "2026-10-04T17:45:27.477283+00:00", "description": "Muestra cultural con la participacion de estudiantes de todos los grados: danzas, musica y folclor.", "fullDescription": "El Festival de la cultura colombiana es una muestra de danzas, musica y folclor preparada por los estudiantes con acompanamiento de los docentes. La invitacion esta abierta a las familias de la comunidad educativa."}, {"id": "ac67de25-074e-4bc3-97b9-c717c21f3131", "date": "2026-11-28", "time": "09:00", "image": null, "title": "Encuentro deportivo intercolegial", "active": true, "endTime": "17:00", "category": "sports", "location": "Cancha del colegio", "created_at": "2026-10-04T17:45:27.477283+00:00", "description": "Participacion del equipo del colegio en los juegos deportivos intercolegiales del municipio.", "fullDescription": "Encuentro deportivo intercolegial en el que participan las selecciones del colegio en las categorias primaria y adolescente. El evento se desarrolla en las instalaciones del colegio y la asistencia de los estudiantes es indicada por los docentes."}]$iejson$::jsonb);

