select * from jsonb_populate_recordset(null::public.school_info, $iejson$[{"id": "3ebb63b7-541a-41ec-b264-69d86b1a7638", "nit": null, "email": "rectoria@jcmutis.edu.co", "phone": null, "vision": "Para el año 2035, la Institución Educativa José Celestino Mutis será reconocida como un referente en innovación y calidad educativa, comprometida con la inclusión, la diversidad y el cuidado del ambiente. Formará estudiantes autónomos, críticos y solidarios, preparados para transformar su entorno y afrontar los retos de un mundo en constante cambio, capaces de responder a los desafíos tecnológicos y sociales, y de contribuir al desarrollo sostenible de la región y del país.", "address": "Calle 8 #12-45, San José del Guaviare", "history": "Formando ciudadanos íntegros y comprometidos con el desarrollo de San José del Guaviare desde 1978.", "mission": "La Institución Educativa José Celestino Mutis forma niños, niñas, jóvenes y adultos mediante una educación integral, inclusiva y de calidad, que fortalece los valores, las competencias académicas y socioemocionales; promueve el pensamiento crítico, el uso responsable de las TIC y el respeto por la diversidad y el ambiente, con el propósito de consolidar líderes íntegros y agentes de cambio comprometidos con la construcción de una sociedad justa y sostenible.", "youtube": null, "facebook": null, "logo_url": "1790998380209-w99r2r14v1.png", "dane_code": null, "instagram": null, "hero_badge": "Año Escolar 2026 — Inscripciones Cerradas", "hero_title": "Colegio José Celestino Mutis", "updated_at": "2026-10-07T21:53:50.998+00:00", "school_name": "Colegio José Celestino Mutis", "hero_subtitle": "", "hero_image_url": "1790998482223-h47ko05h97b.jpg", "hero_badge_color": "#991B1B"}]$iejson$::jsonb);

